// Generated from training-ui/ by scripts/embed-training-assets.mjs.
export const assets: Record<string,{type:string,body:string}> = {"/static/auth-page.js":{"type":"text/javascript; charset=utf-8","body":"let authMode=location.pathname==='/signup'?'signup':'login';\r\nlet setupAllowed=false,reservedEmail=\"\",setupRequired=false,authReady=false,authBusy=false,passwordVisible=false,errorKey='';\r\nconst field=id=>document.getElementById(id);\r\nfunction showAuthError(key){errorKey=key;field('authError').textContent=authMessage(key);field('authError').hidden=!key;if(key)field('authError').focus();}\r\nfunction submitLabel(){return authBusy?(authMode==='signup'?'Creating account…':'Signing in…'):(authMode==='signup'?(setupRequired?'Create leader account':'Create account'):'Log in');}\r\nfunction renderAccountMode(){\r\n  translateAccountText();\r\n  document.title=at('Student Training Platform')+' · '+at(authMode==='signup'?'Sign up':'Log in');\r\n  const signup=authMode==='signup';\r\n  field('signupTab').hidden=!setupRequired;\r\n  field('ownerSetup').hidden=!(signup&&setupRequired&&!setupAllowed);\r\n  field('authForm').hidden=signup&&!setupAllowed;\r\n  field('email').readOnly=signup&&setupAllowed;\r\n  if(signup&&setupAllowed)field('email').value=reservedEmail;\r\n  field('formTitle').textContent=at(signup?(setupRequired?'Create your leader account':'Create your account'):'Welcome back');\r\n  field('formDescription').textContent=at(signup?(setupRequired?'This is the first account. It will be the leader, with full access to the platform.':'Accounts are created by your leader.'):'Log in to your training workspace.');\r\n  field('setupBadge').hidden=!(signup&&setupRequired);\r\n  field('nameField').hidden=!signup;field('fullName').required=signup;\r\n  field('confirmField').hidden=!signup;field('confirmPassword').required=signup;\r\n  field('passwordHint').hidden=!signup;field('password').minLength=signup?15:1;\r\n  field('password').autocomplete=signup?'new-password':'current-password';\r\n  for(const [id,mode] of [['loginTab','login'],['signupTab','signup']]){\r\n    field(id).classList.toggle('active',authMode===mode);field(id).setAttribute('aria-pressed',String(authMode===mode));field(id).disabled=authBusy;\r\n  }\r\n  field('authSubmit').textContent=at(submitLabel());field('authSubmit').disabled=!authReady||authBusy;\r\n  field('authSubmit').setAttribute('aria-busy',String(authBusy));field('languageToggle').disabled=authBusy;\r\n  field('passwordToggle').setAttribute('aria-label',at(passwordVisible?'Hide password':'Show password'));\r\n  field('passwordToggle').title=at(passwordVisible?'Hide password':'Show password');\r\n  if(errorKey)field('authError').textContent=authMessage(errorKey);\r\n}\r\nfunction onLanguageChanged(){renderAccountMode();}\r\nfunction switchMode(mode){if(authBusy)return;authMode=mode;history.replaceState(null,'',mode==='signup'?'/signup':'/login');showAuthError('');renderAccountMode();}\r\nfield('loginTab').addEventListener('click',()=>switchMode('login'));\r\nfield('signupTab').addEventListener('click',()=>switchMode('signup'));\r\nfield('languageToggle').addEventListener('click',()=>setLanguage(language==='ar'?'en':'ar'));\r\nfield('passwordToggle').addEventListener('click',()=>{\r\n  passwordVisible=!passwordVisible;\r\n  field('password').type=field('confirmPassword').type=passwordVisible?'text':'password';\r\n  field('passwordToggle').setAttribute('aria-pressed',String(passwordVisible));renderAccountMode();\r\n});\r\nfield('authForm').addEventListener('submit',async event=>{\r\n  event.preventDefault();if(authBusy||!authReady)return;\r\n  showAuthError('');\r\n  if(authMode==='signup'&&field('password').value!==field('confirmPassword').value){showAuthError('Passwords do not match.');return;}\r\n  const data={email:field('email').value,password:field('password').value};\r\n  if(authMode==='signup')data.name=field('fullName').value;\r\n  authBusy=true;renderAccountMode();\r\n  try{\r\n    const response=await fetch('/api/auth/'+(authMode==='signup'?'signup':'login'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});\r\n    const result=await response.json().catch(()=>({}));\r\n    if(!response.ok){showAuthError(typeof result.detail==='string'?result.detail:'Please check the entered values.');return;}\r\n    location.replace('/');\r\n  }catch(_){showAuthError('Unable to reach the server. Refresh the page and try again.');}\r\n  finally{authBusy=false;renderAccountMode();}\r\n});\r\napplyLanguage();renderAccountMode();\r\n(async()=>{\r\n  try{\r\n    const response=await fetch('/api/auth/status',{credentials:'same-origin'});\r\n    if(!response.ok)throw new Error();\r\n    const status=await response.json();setupRequired=status.setup_required;setupAllowed=status.admin_setup_allowed;reservedEmail=status.reserved_email||'';authReady=true;\r\n    if(!setupRequired&&authMode==='signup'){switchMode('login');showAuthError('Accounts are created by your leader.');}\r\n    if(setupRequired)switchMode('signup');\r\n    if(new URLSearchParams(location.search).has('expired'))showAuthError('Your session ended. Please log in again.');\r\n    renderAccountMode();\r\n  }catch(_){showAuthError('Unable to reach the server. Refresh the page and try again.');}\r\n})();\r\n"},"/static/auth-shared.js":{"type":"text/javascript; charset=utf-8","body":"// English keys keep account text separate from stored application values.\r\nconst AUTH_AR = {\r\n  'Student Training Platform':'منصة التدريب الطلابي',\r\n  'STUDENT SUPPORT & TRAINING':'الدعم والتدريب الطلابي',\r\n  'One workspace. A stronger team.':'مساحة واحدة لفريق أكثر تنظيمًا.',\r\n  'Plan training, follow progress, and keep your team connected.':'خططي للتدريب، وتابعي التقدم، ونظّمي عمل فريقك في مكان واحد.',\r\n  'Organize events':'تنظيم الفعاليات',\r\n  'Track progress':'متابعة الإنجاز',\r\n  'Clear team roles':'أدوار واضحة للفريق',\r\n  'Team workspace · 1448 AH':'مساحة الفريق · 1448هـ',\r\n  'Welcome back':'أهلًا بعودتك',\r\n  'Log in to your training workspace.':'سجلي الدخول إلى مساحة التدريب الخاصة بك.',\r\n  'Log in':'تسجيل الدخول',\r\n  'Sign up':'إنشاء حساب',\r\n  'Create account':'إنشاء الحساب',\r\n  'Create your account':'أنشئي حسابك',\r\n  'Join the workspace as a team member. Your leader can change your role later.':'انضمي إلى مساحة العمل كعضو في الفريق. يمكن للقائد تعديل دورك لاحقًا.',\r\n  'Create your leader account':'إنشاء حساب القائد',\r\n  'First-time setup':'الإعداد الأول',\r\n  'This is the first account. It will be the leader, with full access to the platform.':'هذا هو الحساب الأول، وسيصبح حساب القائد بصلاحيات كاملة لإدارة المنصة.',\r\n  'Create leader account':'إنشاء حساب القائد',\r\n  'Full name':'الاسم الكامل',\r\n  'Email address':'البريد الإلكتروني',\r\n  'Password':'كلمة المرور',\r\n  'Confirm password':'تأكيد كلمة المرور',\r\n  'Use at least 15 characters.':'استخدمي 15 حرفًا على الأقل.',\r\n  'Show password':'إظهار كلمة المرور',\r\n  'Hide password':'إخفاء كلمة المرور',\r\n  'Signing in…':'جارٍ تسجيل الدخول…',\r\n  'Creating account…':'جارٍ إنشاء الحساب…',\r\n  'Passwords do not match.':'كلمتا المرور غير متطابقتين.',\r\n  'Please check the entered values.':'راجعي البيانات المدخلة.',\r\n  'Please log in to continue.':'سجلي الدخول للمتابعة.',\r\n  'Your session ended. Please log in again.':'انتهت جلستك. سجلي الدخول مجددًا.',\r\n  'Unable to reach the server. Refresh the page and try again.':'تعذر الاتصال بالخادم. حدّثي الصفحة وحاولي مجددًا.',\r\n  'Email or password is incorrect.':'البريد الإلكتروني أو كلمة المرور غير صحيحة.',\r\n  'This email address is already in use.':'هذا البريد الإلكتروني مستخدم بالفعل.',\r\n  'Enter a valid email address.':'أدخلي بريدًا إلكترونيًا صالحًا.',\r\n  'Use a password between 12 and 128 characters.':'استخدمي كلمة مرور من 12 إلى 128 حرفًا.',\r\n  'Enter a name between 1 and 100 characters.':'أدخلي اسمًا من حرف واحد إلى 100 حرف.',\r\n  'Too many attempts. Try again in 15 minutes.':'محاولات كثيرة. حاولي مجددًا بعد 15 دقيقة.',\r\n  'Refresh the page and try again.':'حدّثي الصفحة وحاولي مجددًا.',\r\n  'Request origin was rejected.':'تم رفض مصدر الطلب.',\r\n  'JSON requests are required.':'صيغة الطلب غير صالحة.',\r\n  'Only the leader can manage accounts and approvals.':'القائد فقط يمكنه إدارة الحسابات والاعتمادات.',\r\n  'Your role cannot make this change.':'دورك لا يسمح بإجراء هذا التغيير.',\r\n  'Invalid role.':'الدور غير صالح.',\r\n  'Account not found.':'الحساب غير موجود.',\r\n  'Keep at least one active leader account.':'يجب الإبقاء على حساب قائد نشط واحد على الأقل.',\r\n  'Only the leader can reopen a closed event.':'القائد فقط يمكنه إعادة فتح فعالية مغلقة.',\r\n  'Only the leader can close an event.':'القائد فقط يمكنه إغلاق فعالية.',\r\n  'Only the leader can approve or change an approved document.':'القائد فقط يمكنه اعتماد الملفات أو تعديل ملف معتمد.',\r\n  'Approve the four documents before closing an event.':'اعتمدي المرفقات الأربعة قبل إغلاق الفعالية.',\r\n  'Failed to fetch':'تعذر الاتصال بالخادم',\r\n  'Log out':'تسجيل الخروج',\r\n  'Leader / Admin':'القائد / المسؤول',\r\n  'Program Coordinator':'منسق البرنامج',\r\n  'Team Member':'عضو الفريق',\r\n  'Viewer':'مستعرض',\r\n  'Accounts & permissions':'الحسابات والصلاحيات',\r\n  'The leader controls access and assigns each account a role.':'يتحكم القائد في الوصول ويحدد دور كل حساب.',\r\n  'Add account':'إضافة حساب',\r\n  'Edit account':'تعديل الحساب',\r\n  'Save account':'حفظ الحساب',\r\n  'No login yet':'بلا تسجيل دخول بعد',\r\n  'Role permissions':'صلاحيات الأدوار',\r\n  'Full access, account management, document approvals, and event closure.':'وصول كامل، وإدارة الحسابات، واعتماد المرفقات، وإغلاق الفعاليات.',\r\n  'Manage events, team tasks, and unapproved documents.':'إدارة الفعاليات ومهام الفريق والمرفقات غير المعتمدة.',\r\n  'View the workspace and update team task status.':'عرض مساحة العمل وتحديث حالات مهام الفريق.',\r\n  'Read-only access to the workspace.':'عرض مساحة العمل فقط.',\r\n  'Role':'الدور',\r\n  'New password (optional)':'كلمة مرور جديدة (اختياري)',\r\n  'Leave blank to keep the current password. Setting a password enables login and signs out existing sessions.':'اتركي الحقل فارغًا للإبقاء على كلمة المرور. تعيين كلمة مرور يتيح تسجيل الدخول وينهي الجلسات الحالية.',\r\n  'Use at least 15 characters. Share the password privately with the account owner.':'استخدمي 15 حرفًا على الأقل، وشاركي كلمة المرور بشكل خاص مع صاحب الحساب.',\r\n  'Active account':'حساب نشط',\r\n  'Cancel':'إلغاء',\r\n  'Your team shares this workspace. Your leader manages accounts, permissions, and password resets.':'يشترك فريقك في مساحة العمل. يدير القائد الحسابات والصلاحيات وإعادة تعيين كلمات المرور.',\r\n  'Contact your leader for an account or password reset.':'تواصلي مع القائد لإنشاء حساب أو إعادة تعيين كلمة المرور.',\r\n};\r\nObject.assign(AUTH_AR,{\"Tasks and linked events are visible to everyone in this workspace.\": \"المهام والفعاليات المرتبطة بها ظاهرة للجميع في مساحة العمل.\", \"Everyone can see this task, including members who are not assigned to it.\": \"يمكن للجميع رؤية هذه المهمة، بما في ذلك الأعضاء غير المكلّفين بها.\", \"Refresh\": \"تحديث\", \"New task\": \"مهمة جديدة\", \"Updates automatically while this page is open.\": \"تتحدث البيانات تلقائيًا أثناء فتح الصفحة.\", \"Updates paused. Use Refresh to retry.\": \"توقف التحديث مؤقتًا. استخدمي زر التحديث للمحاولة مجددًا.\", \"Assigned to\": \"المكلّف بالمهمة\", \"Assigned to you\": \"مهمة مكلّفة لك\", \"Unassigned\": \"غير مكلّفة\", \"Due\": \"الاستحقاق\", \"Priority\": \"الأولوية\", \"Related event\": \"الفعالية المرتبطة\", \"General task\": \"مهمة عامة\", \"Task status\": \"حالة المهمة\", \"View details\": \"عرض التفاصيل\", \"No shared tasks yet.\": \"لا توجد مهام مشتركة بعد.\", \"Instructions & notes\": \"التعليمات والملاحظات\", \"No additional instructions.\": \"لا توجد تعليمات إضافية.\", \"Open linked event\": \"فتح الفعالية المرتبطة\", \"Close\": \"إغلاق\", \"The linked event no longer exists.\": \"الفعالية المرتبطة لم تعد موجودة.\", \"This assignee is unavailable. Refresh and choose an active account.\": \"هذا المكلّف غير متاح. حدّثي الصفحة واختاري حسابًا نشطًا.\"});\r\nObject.assign(AUTH_AR,{\"Team workspace · 1448 AH\": \"مساحة الفريق · 1448هـ\", \"Only the site owner can activate the administrator account.\": \"مالك الموقع فقط يمكنه تفعيل حساب المسؤول.\", \"Continue as site owner\": \"المتابعة بصفتك مالك الموقع\", \"Accounts are created by your leader.\": \"ينشئ قائد الفريق الحسابات.\", \"Only the site owner can set up the administrator.\": \"مالك الموقع فقط يمكنه إعداد حساب المسؤول.\", \"Use the reserved administrator email.\": \"استخدمي البريد الإلكتروني المحجوز للمسؤول.\", \"Administrator setup is already complete.\": \"اكتمل إعداد حساب المسؤول بالفعل.\", \"Use a password between 15 and 128 characters.\": \"استخدمي كلمة مرور من 15 إلى 128 حرفًا.\", \"Choose a less predictable password without your name or email.\": \"اختاري كلمة مرور يصعب توقعها ولا تتضمن اسمك أو بريدك الإلكتروني.\", \"Document is closed, approved, or unavailable.\": \"الملف مغلق أو معتمد أو غير متاح.\", \"Use a valid HTTP or HTTPS file link.\": \"أدخلي رابط ملف صالحًا يبدأ بـ HTTP أو HTTPS.\", \"Approve the four documents and finish the event before closing.\": \"اعتمدي المرفقات الأربعة وأنهي الفعالية قبل إغلاقها.\", \"Workspace storage is unavailable.\": \"تعذر الوصول إلى مساحة تخزين الفريق.\", \"Invalid date.\": \"التاريخ غير صالح.\", \"The request could not be completed. Please refresh and try again.\": \"تعذر إتمام الطلب. حدّثي الصفحة وحاولي مجددًا.\"});\r\nfunction at(key){return language==='ar'?(AUTH_AR[key]??key):key;}\r\nfunction authMessage(message){return language==='ar'?(AUTH_AR[message]??message):tr(message);}\r\nfunction roleLabel(role){return at(({admin:'Leader / Admin',coordinator:'Program Coordinator',member:'Team Member',viewer:'Viewer'})[role]||'Viewer');}\r\nfunction translateAccountText(){document.querySelectorAll('[data-auth-i18n]').forEach(node=>node.textContent=at(node.dataset.authI18n));}\r\n"},"/static/auth.css":{"type":"text/css; charset=utf-8","body":":root{font-family:'Segoe UI',Tahoma,sans-serif;color:#233042;background:#f4f6fa;line-height:1.5;color-scheme:light}*{box-sizing:border-box}body{margin:0}button,input{font:inherit}button{cursor:pointer}button:disabled{cursor:default;opacity:.55}[hidden]{display:none!important}.auth-page{min-height:100vh;display:grid;grid-template-columns:minmax(320px,1fr) minmax(440px,1fr)}.brand-panel{position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between;gap:55px;padding:48px clamp(28px,5vw,80px);background:#173353;color:#fff}.brand-panel:after{content:'';position:absolute;width:440px;height:440px;border:1px solid #ffffff0d;border-radius:50%;inset-inline-end:-270px;bottom:-120px;box-shadow:0 0 0 65px #ffffff04,0 0 0 130px #ffffff03;pointer-events:none}.brand-lockup{display:flex;align-items:center;gap:14px}.brand-mark{display:grid;place-items:center;width:48px;height:48px;flex-shrink:0;border:1px solid #7192b366;border-radius:13px;color:#d5e5f4}.brand-mark svg{width:29px;height:29px}.eyebrow{font-size:10px;letter-spacing:.1em;color:#b4cadd}.brand-name{font-size:17px;font-weight:600;margin:3px 0}.brand-copy{max-width:430px;position:relative;z-index:1}.brand-line{display:block;width:40px;height:4px;background:#8bb8df;border-radius:3px;margin-bottom:24px}.brand-copy h1{font-size:clamp(30px,3.1vw,44px);line-height:1.22;letter-spacing:-.02em;max-width:400px;margin:0 0 20px}.brand-copy>p{color:#bfd1e3;font-size:15px;max-width:360px;line-height:1.8;margin:0}.feature-list{display:grid;gap:17px;margin-top:40px}.feature-list>span{display:flex;align-items:center;gap:13px;font-size:13px;color:#dce8f4}.feature-list b{font-size:10px;font-weight:500;color:#9bb9d5;border:1px solid #6b8baa55;display:grid;place-items:center;width:27px;height:27px;border-radius:7px;direction:ltr}.brand-footer{font-size:11px;color:#a5bed4;margin:0;position:relative;z-index:1}.form-panel{display:flex;flex-direction:column;align-items:center;padding:30px 40px 45px}.form-toolbar{display:flex;justify-content:flex-end;width:100%;max-width:560px}.language-toggle{display:inline-flex;align-items:center;justify-content:center;gap:9px;border:1px solid #c6d5e5;border-radius:10px;color:#174b7a;background:white;min-width:128px;min-height:44px;padding:9px 16px;font-size:14px;font-weight:700;transition:background .15s,transform .15s}.language-toggle svg{width:20px;height:20px}.language-toggle:hover{background:#e7eff8}.language-toggle:active{transform:translateY(1px)}.auth-card{background:#fff;width:100%;max-width:430px;padding:30px;border:1px solid #e0e7f0;border-radius:18px;box-shadow:0 7px 30px #17335308;margin:auto 0}.mode-switch{display:grid;grid-template-columns:1fr 1fr;gap:4px;background:#eff3f8;border:1px solid #e4eaf2;padding:4px;border-radius:10px;margin-bottom:27px}.mode-switch button{border:0;border-radius:7px;min-height:41px;font-size:13px;color:#6b7c91;background:transparent;font-weight:600;transition:background .15s,color .15s}.mode-switch button.active{background:#fff;box-shadow:0 1px 5px #17335315;color:#174b7a}.mode-switch button:hover{color:#174b7a}.auth-card h2{font-size:26px;line-height:1.3;letter-spacing:-.02em;margin:0 0 9px}.description{font-size:13px;line-height:1.7;color:#6b7d92;margin:0 0 25px}.setup-badge{display:inline-flex;align-items:center;border-radius:6px;background:#e6effb;color:#235788;font-size:11px;font-weight:600;padding:4px 9px;margin-bottom:12px}.field{margin-bottom:18px}.field label{display:block;margin-bottom:7px;font-size:12px;font-weight:600}.field input{display:block;width:100%;min-width:0;height:46px;padding:11px 12px;border:1px solid #cfd9e7;border-radius:8px;background:#fff;color:#233042;font-size:14px;transition:border-color .15s,box-shadow .15s}.field input:focus{outline:0;border-color:#3985bd;box-shadow:0 0 0 3px #3985bd17}.password-row{position:relative}.password-row input{padding-inline-end:48px}.password-row button{position:absolute;inset-inline-end:3px;top:3px;width:40px;height:40px;display:grid;place-items:center;background:transparent;border:0;border-radius:6px;color:#73859a}.password-row svg{width:19px;height:19px}.password-row button:hover{background:#eff4fa;color:#235788}.field-hint{font-size:11px;line-height:1.5;color:#738195;margin:7px 0 0}.primary-button{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;min-height:47px;background:#235788;border:1px solid #173f69;border-radius:9px;color:white;font-size:14px;font-weight:600;transition:background .15s,transform .15s}.primary-button:hover:enabled{background:#173f69}.primary-button:active:enabled{transform:translateY(1px)}.primary-button[aria-busy=true]:before{content:'';width:15px;height:15px;border:2px solid #ffffff50;border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite}.account-help{border-top:1px solid #e8edf4;padding-top:19px;margin:23px 0 0;font-size:11px;line-height:1.75;color:#7a8b9f}.form-error{background:#fff0f0;color:#993d46;border:1px solid #f4d4d7;border-radius:8px;padding:11px 12px;font-size:12px;line-height:1.6;margin-bottom:18px}button:focus-visible{outline:3px solid #3985bd;outline-offset:3px}.sr-only{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@keyframes spin{to{transform:rotate(360deg)}}@media(min-height:900px){.auth-card{margin:auto 0;transform:translateY(-10px)}}@media(max-width:850px){.auth-page{grid-template-columns:1fr}.brand-panel{padding:22px 25px;gap:0}.brand-copy,.brand-footer{display:none}.brand-mark{width:40px;height:40px}.brand-name{font-size:16px}.form-panel{padding:18px 20px 35px;gap:18px}.auth-card{margin:0;max-width:460px;transform:none}.form-toolbar{max-width:460px}.auth-card{padding:25px}.eyebrow{font-size:9px}}@media(max-width:380px){.form-panel{padding-inline:14px}.auth-card{padding:21px}.auth-card h2{font-size:24px}.brand-panel{padding-inline:20px}}@media(prefers-reduced-motion:reduce){*,*:before{animation:none!important;transition:none!important}}\r\n\r\n.owner-setup{padding:18px;border:1px solid #cfd9e7;border-radius:12px;background:#f5f8fc;line-height:1.7;margin-bottom:18px}.owner-setup .primary-button{display:flex;align-items:center;justify-content:center;text-decoration:none;min-height:48px}.owner-setup p{margin:0 0 14px}[hidden]{display:none!important}\r\n"},"/static/auth.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\r\n<html lang=\"ar\" dir=\"rtl\">\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n  <title>منصة التدريب الطلابي</title>\r\n  <link rel=\"stylesheet\" href=\"/static/auth.css\">\r\n  <script src=\"/static/i18n.js\" defer></script>\r\n  <script src=\"/static/auth-shared.js\" defer></script>\r\n  <script src=\"/static/auth-page.js\" defer></script>\r\n</head>\r\n<body>\r\n  <main class=\"auth-page\">\r\n    <section class=\"brand-panel\" aria-labelledby=\"brandTitle\">\r\n      <div class=\"brand-lockup\"><span class=\"brand-mark\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.7\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.7\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.7\"/><path d=\"m14 18 3 3 5-7\"/></svg></span><div><span class=\"eyebrow\" data-auth-i18n=\"STUDENT SUPPORT & TRAINING\"></span><p class=\"brand-name\" data-auth-i18n=\"Student Training Platform\"></p></div></div>\r\n      <div class=\"brand-copy\"><span class=\"brand-line\" aria-hidden=\"true\"></span><h1 id=\"brandTitle\" data-auth-i18n=\"One workspace. A stronger team.\"></h1><p data-auth-i18n=\"Plan training, follow progress, and keep your team connected.\"></p><div class=\"feature-list\"><span><b aria-hidden=\"true\">01</b><span data-auth-i18n=\"Organize events\"></span></span><span><b aria-hidden=\"true\">02</b><span data-auth-i18n=\"Track progress\"></span></span><span><b aria-hidden=\"true\">03</b><span data-auth-i18n=\"Clear team roles\"></span></span></div></div>\r\n      <p class=\"brand-footer\" data-auth-i18n=\"Team workspace · 1448 AH\"></p>\r\n    </section>\r\n    <section class=\"form-panel\" aria-labelledby=\"formTitle\">\r\n      <div class=\"form-toolbar\"><button id=\"languageToggle\" class=\"language-toggle\" type=\"button\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M3 12h18M12 3c3 3 4 6 4 9s-1 6-4 9c-3-3-4-6-4-9s1-6 4-9Z\"/></svg><span id=\"languageName\" lang=\"en\" dir=\"ltr\">English</span></button><span id=\"languageStatus\" class=\"sr-only\" role=\"status\" aria-live=\"polite\"></span></div>\r\n      <div class=\"auth-card\">\r\n        <div class=\"mode-switch\" aria-label=\"Account access\"><button id=\"loginTab\" type=\"button\" data-auth-i18n=\"Log in\"></button><button id=\"signupTab\" type=\"button\" data-auth-i18n=\"Sign up\"></button></div>\r\n        <div id=\"setupBadge\" class=\"setup-badge\" hidden data-auth-i18n=\"First-time setup\"></div>\r\n        <h2 id=\"formTitle\"></h2><p id=\"formDescription\" class=\"description\"></p>\r\n        <div id=\"authError\" class=\"form-error\" role=\"alert\" tabindex=\"-1\" hidden></div>\r\n        <div id=\"ownerSetup\" class=\"owner-setup\" hidden><p data-auth-i18n=\"Only the site owner can activate the administrator account.\"></p><a class=\"primary-button\" href=\"/signin-with-chatgpt?return_to=%2Fsignup\" target=\"_top\" data-auth-i18n=\"Continue as site owner\"></a></div><form id=\"authForm\">\r\n          <div id=\"nameField\" class=\"field\" hidden><label for=\"fullName\" data-auth-i18n=\"Full name\"></label><input id=\"fullName\" name=\"name\" autocomplete=\"name\" maxlength=\"100\"></div>\r\n          <div class=\"field\"><label for=\"email\" data-auth-i18n=\"Email address\"></label><input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"username\" inputmode=\"email\" required maxlength=\"254\" dir=\"ltr\"></div>\r\n          <div class=\"field\"><label for=\"password\" data-auth-i18n=\"Password\"></label><div class=\"password-row\"><input id=\"password\" name=\"password\" type=\"password\" autocomplete=\"current-password\" required maxlength=\"128\" aria-describedby=\"passwordHint\"><button id=\"passwordToggle\" type=\"button\" aria-pressed=\"false\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" aria-hidden=\"true\"><path d=\"M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg></button></div><p id=\"passwordHint\" class=\"field-hint\" hidden data-auth-i18n=\"Use at least 15 characters.\"></p></div>\r\n          <div id=\"confirmField\" class=\"field\" hidden><label for=\"confirmPassword\" data-auth-i18n=\"Confirm password\"></label><input id=\"confirmPassword\" name=\"confirmPassword\" type=\"password\" autocomplete=\"new-password\" maxlength=\"128\"></div>\r\n          <button id=\"authSubmit\" class=\"primary-button\" type=\"submit\" disabled></button>\r\n        </form>\r\n        <p class=\"account-help\" data-auth-i18n=\"Contact your leader for an account or password reset.\"></p>\r\n      </div>\r\n    </section>\r\n  </main>\r\n</body>\r\n</html>\r\n"},"/static/i18n.js":{"type":"text/javascript; charset=utf-8","body":"// Translate UI source text only. Persisted values and user content stay unchanged.\r\n\r\nconst EN = {\r\n\r\n  \"منصة إدارة التدريب الطلابي - مساحة الفريق\": \"Student Training Platform - Local Edition\",\r\n\r\n  \"منصة التدريب الطلابي\": \"Student Training Platform\",\r\n\r\n  \"وحدة الدعم والتدريب الطلابي – 1448هـ\": \"Student Support & Training Unit - 1448 AH\",\r\n\r\n  \"مساحة مشتركة لتنظيم عمل الفريق\": \"Local edition on this device\",\r\n\r\n  \"مساحة الفريق\": \"Demo data only\",\r\n\r\n  \"هذه نسخة محلية أولية بلا تسجيل دخول فعلي أو ربط OneDrive. لا تُدخلي بيانات طلاب أو ملفات سرية قبل اعتماد الاستضافة ونظام الصلاحيات.\": \"This local prototype has no sign-in or OneDrive connection. Do not enter student records or confidential files until hosting and access controls are approved.\",\r\n\r\n  \"تُحفظ السجلات في مساحة الفريق المشتركة، وتظهر التحديثات لجميع الأعضاء.\": \"Records are saved in a SQLite file in the project folder. This interface runs locally at 127.0.0.1 only.\",\r\n\r\n  \"لوحة القيادة\": \"Dashboard\",\r\n\r\n  \"التقويم الفصلي\": \"Semester Calendar\",\r\n\r\n  \"الدورات والفعاليات\": \"Courses & Events\",\r\n\r\n  \"متابعة المرفقات\": \"Document Tracking\",\r\n\r\n  \"مهام الفريق\": \"Team Tasks\",\r\n\r\n  \"المستخدمون\": \"Users\",\r\n\r\n  \"المسارات المعتمدة\": \"Approved Tracks\",\r\n\r\n  \"البرامج المعتمدة\": \"Approved Programs\",\r\n\r\n  \"الفعاليات المسجلة\": \"Registered Events\",\r\n\r\n  \"المهام المتأخرة\": \"Overdue Tasks\",\r\n\r\n  \"الفعاليات حسب المسار\": \"Events by Track\",\r\n\r\n  \"متابعة التنفيذ\": \"Progress Overview\",\r\n\r\n  \"فعاليات منتهية أو مغلقة\": \"Finished or closed events\",\r\n\r\n  \"فعاليات مجدولة\": \"Scheduled events\",\r\n\r\n  \"مهام تحت العمل\": \"Tasks in progress\",\r\n\r\n  \"عرض التقويم\": \"View Calendar\",\r\n\r\n  \"متابعة الملفات\": \"Track Documents\",\r\n\r\n  \"جميع المسارات\": \"All Tracks\",\r\n\r\n  \"المسار العام\": \"General Track\",\r\n\r\n  \"برنامج الثقافة المالية\": \"Financial Literacy Program\",\r\n\r\n  \"برنامج مهارات المستقبل\": \"Future Skills Program\",\r\n\r\n  \"برنامج السلوك المهني\": \"Professional Conduct Program\",\r\n\r\n  \"برنامج البحث والابتكار العلمي\": \"Research & Scientific Innovation Program\",\r\n\r\n  \"المسار التخصصي\": \"Specialist Track\",\r\n\r\n  \"برنامج المهارات الصحية التطبيقية\": \"Applied Health Skills Program\",\r\n\r\n  \"برنامج التقنيات والحلول العلمية\": \"Technology & Scientific Solutions Program\",\r\n\r\n  \"برنامج الإدارة والريادة المؤسسية\": \"Management & Institutional Entrepreneurship Program\",\r\n\r\n  \"برنامج الدراسات والمهارات الإنسانية\": \"Humanities Studies & Skills Program\",\r\n\r\n  \"مسار المبادرات الطلابية\": \"Student Initiatives Track\",\r\n\r\n  \"برنامج القيادة والتأثير الطلابي\": \"Student Leadership & Impact Program\",\r\n\r\n  \"برنامج الأدوات الابتكارية\": \"Innovation Tools Program\",\r\n\r\n  \"برنامج المهارات الإعلامية\": \"Media Skills Program\",\r\n\r\n  \"برنامج صناعة المشاريع الطلابية\": \"Student Project Development Program\",\r\n\r\n  \"المسار المهني\": \"Career Track\",\r\n\r\n  \"برنامج التمكين الاحترافي\": \"Professional Development Program\",\r\n\r\n  \"برنامج ريادة الأعمال\": \"Entrepreneurship Program\",\r\n\r\n  \"برنامج الشهادات التقنية والرقمية\": \"Technical & Digital Certifications Program\",\r\n\r\n  \"برنامج الشهادات الاحترافية الإدارية\": \"Professional Management Certifications Program\",\r\n\r\n  \"المسار\": \"Track\",\r\n\r\n  \"شهري\": \"Monthly\",\r\n\r\n  \"أسبوعي\": \"Weekly\",\r\n\r\n  \"فعالية جديدة\": \"New Event\",\r\n\r\n  \"إضافة فعالية\": \"Add Event\",\r\n\r\n  \"تعديل الفعالية\": \"Edit Event\",\r\n\r\n  \"السابق\": \"Previous\",\r\n\r\n  \"التالي\": \"Next\",\r\n\r\n  \"لقاءات\": \"Sessions on\",\r\n\r\n  \"اللقاءات\": \"Sessions\",\r\n\r\n  \"المزيد\": \"more\",\r\n\r\n  \"فتح\": \"Open\",\r\n\r\n  \"لا توجد لقاءات في هذا اليوم.\": \"No sessions on this day.\",\r\n\r\n  \"تصفية المسار\": \"Filter by Track\",\r\n\r\n  \"الفعالية\": \"Event\",\r\n\r\n  \"فعالية\": \"events\",\r\n\r\n  \"البرنامج\": \"Program\",\r\n\r\n  \"الفترة\": \"Date Range\",\r\n\r\n  \"الحالة\": \"Status\",\r\n\r\n  \"إلى\": \"to\",\r\n\r\n  \"التفاصيل\": \"Details\",\r\n\r\n  \"لم تُسجل فعاليات بعد.\": \"No events have been added yet.\",\r\n\r\n  \"اسم الفعالية\": \"Event Name\",\r\n\r\n  \"البرنامج المعتمد\": \"Approved Program\",\r\n\r\n  \"تاريخ البداية\": \"Start Date\",\r\n\r\n  \"تاريخ النهاية\": \"End Date\",\r\n\r\n  \"نمط الجدولة\": \"Schedule Type\",\r\n\r\n  \"يوم واحد\": \"Single Day\",\r\n\r\n  \"أيام متتالية\": \"Consecutive Days\",\r\n\r\n  \"لقاءات أسبوعية\": \"Weekly Sessions\",\r\n\r\n  \"مواعيد مخصصة\": \"Custom Dates\",\r\n\r\n  \"وقت البداية\": \"Start Time\",\r\n\r\n  \"وقت النهاية\": \"End Time\",\r\n\r\n  \"المنسق\": \"Coordinator\",\r\n\r\n  \"أيام اللقاءات الأسبوعية\": \"Weekly Session Days\",\r\n\r\n  \"تواريخ اللقاءات المخصصة (تاريخ في كل سطر)\": \"Custom Session Dates (one date per line)\",\r\n\r\n  \"حفظ الفعالية\": \"Save Event\",\r\n\r\n  \"إلغاء\": \"Cancel\",\r\n\r\n  \"غير محدد\": \"Not assigned\",\r\n\r\n  \"تعديل\": \"Edit\",\r\n\r\n  \"المرفقات\": \"Documents\",\r\n\r\n  \"حذف\": \"Delete\",\r\n\r\n  \"إغلاق\": \"Close\",\r\n\r\n  \"هل تريد حذف الفعالية نهائيًا؟\": \"Permanently delete this event?\",\r\n\r\n  \"توثيق الفعاليات المنتهية\": \"Completed Event Documentation\",\r\n\r\n  \"أضيفي روابط الملفات وراجعي حالة اعتمادها هنا. لا توجد مزامنة تلقائية مع OneDrive.\": \"Documents are recorded manually in this prototype to simulate OneDrive status. Automatic sync is not available yet.\",\r\n\r\n  \"المرفقات الموجودة\": \"Documents Present\",\r\n\r\n  \"المعتمدة\": \"Approved\",\r\n\r\n  \"مراجعة المرفقات\": \"Review Documents\",\r\n\r\n  \"لم تُحدد فعاليات منتهية بعد. حدّثي حالة إحدى الفعاليات إلى «منتهية» لتجربة التوثيق.\": \"No finished events yet. Set an event status to Finished to try document tracking.\",\r\n\r\n  \"مرفقات\": \"Documents\",\r\n\r\n  \"تُحدّث حالة الملفات يدويًا من قِبل الفريق.\": \"File availability is simulated and is not read from OneDrive.\",\r\n\r\n  \"موجود\": \"Present\",\r\n\r\n  \"معتمد\": \"Approved\",\r\n\r\n  \"رابط الملف (اختياري)\": \"File URL (optional)\",\r\n\r\n  \"حفظ حالة الملف\": \"Save Document Status\",\r\n\r\n  \"اعتماد إغلاق الفعالية\": \"Approve Event Closure\",\r\n\r\n  \"التقرير الختامي\": \"Final Report\",\r\n\r\n  \"الشواهد\": \"Supporting Evidence\",\r\n\r\n  \"ملف الحضور\": \"Attendance File\",\r\n\r\n  \"ملف التقييم\": \"Evaluation File\",\r\n\r\n  \"تحت الإعداد\": \"In Preparation\",\r\n\r\n  \"مجدولة\": \"Scheduled\",\r\n\r\n  \"جارٍ التنفيذ\": \"In Progress\",\r\n\r\n  \"منتهية\": \"Finished\",\r\n\r\n  \"مغلقة\": \"Closed\",\r\n\r\n  \"ملغاة\": \"Cancelled\",\r\n\r\n  \"مكتمل\": \"Complete\",\r\n\r\n  \"بانتظار الاعتماد\": \"Awaiting Approval\",\r\n\r\n  \"ناقص\": \"Missing\",\r\n\r\n  \"إجمالي المهام\": \"Total Tasks\",\r\n\r\n  \"تحت العمل\": \"In Progress\",\r\n\r\n  \"مكتملة\": \"Completed\",\r\n\r\n  \"متأخرة\": \"Overdue\",\r\n\r\n  \"مهمة جديدة\": \"New Task\",\r\n\r\n  \"المسؤول\": \"Assigned To\",\r\n\r\n  \"الاستحقاق\": \"Due\",\r\n\r\n  \"الأولوية\": \"Priority\",\r\n\r\n  \"غير مكتمل\": \"Incomplete\",\r\n\r\n  \"لا توجد مهام بعد.\": \"No tasks yet.\",\r\n\r\n  \"إدارة مهام الفريق\": \"Team Task Management\",\r\n\r\n  \"تعديل المهمة\": \"Edit Task\",\r\n\r\n  \"إضافة مهمة\": \"Add Task\",\r\n\r\n  \"العنوان\": \"Title\",\r\n\r\n  \"تاريخ الاستحقاق\": \"Due Date\",\r\n\r\n  \"منخفضة\": \"Low\",\r\n\r\n  \"متوسطة\": \"Medium\",\r\n\r\n  \"عالية\": \"High\",\r\n\r\n  \"الفعالية المرتبطة\": \"Related Event\",\r\n\r\n  \"مهمة عامة\": \"General Task\",\r\n\r\n  \"ملاحظات\": \"Notes\",\r\n\r\n  \"حفظ\": \"Save\",\r\n\r\n  \"حذف المهمة؟\": \"Delete this task?\",\r\n\r\n  \"قائمة مستخدمي المنصة\": \"Platform Users\",\r\n\r\n  \"مستخدم تجريبي\": \"Demo User\",\r\n\r\n  \"هذه قائمة تحضيرية للصلاحيات فقط. لا توجد حسابات دخول حقيقية، ولا تمنع هذه الواجهة أي شخص يستخدم الجهاز من إجراء تعديلات.\": \"This list is for planning access roles only. There are no real sign-in accounts, and anyone using this device can make changes.\",\r\n\r\n  \"منسق برنامج\": \"Program Coordinator\",\r\n\r\n  \"عضو الفريق\": \"Team Member\",\r\n\r\n  \"مستعرض\": \"Viewer\",\r\n\r\n  \"نشط\": \"Active\",\r\n\r\n  \"معطل\": \"Inactive\",\r\n\r\n  \"لم تُضف حسابات تجريبية.\": \"No demo users have been added.\",\r\n\r\n  \"الأدوار المعتمدة\": \"Defined Roles\",\r\n\r\n  \"مشرفة المنصة: الإدارة الكاملة والاعتمادات، وستُفعّل بعد إنشاء المصادقة الحقيقية.\": \"Platform Administrator: full management and approvals, available after real authentication is implemented.\",\r\n\r\n  \"منسق البرنامج: تنظيم الدورات والمرفقات والمهام المصرح بها.\": \"Program Coordinator: manage assigned courses, documents, and tasks.\",\r\n\r\n  \"عضو الفريق: تحديث المهام والملفات ضمن الصلاحيات.\": \"Team Member: update tasks and files within assigned permissions.\",\r\n\r\n  \"مستعرض: الاطلاع فقط.\": \"Viewer: read-only access.\",\r\n\r\n  \"إدارة المستخدمين\": \"User Management\",\r\n\r\n  \"تعديل مستخدم\": \"Edit User\",\r\n\r\n  \"إضافة مستخدم تجريبي\": \"Add Demo User\",\r\n\r\n  \"الاسم\": \"Name\",\r\n\r\n  \"البريد الإلكتروني\": \"Email Address\",\r\n\r\n  \"الدور\": \"Role\",\r\n\r\n  \"حساب نشط\": \"Active Account\",\r\n\r\n  \"أحد\": \"Sun\",\r\n\r\n  \"اثنين\": \"Mon\",\r\n\r\n  \"ثلاثاء\": \"Tue\",\r\n\r\n  \"أربعاء\": \"Wed\",\r\n\r\n  \"خميس\": \"Thu\",\r\n\r\n  \"جمعة\": \"Fri\",\r\n\r\n  \"سبت\": \"Sat\",\r\n\r\n  \"الأحد\": \"Sunday\",\r\n\r\n  \"الاثنين\": \"Monday\",\r\n\r\n  \"الثلاثاء\": \"Tuesday\",\r\n\r\n  \"الأربعاء\": \"Wednesday\",\r\n\r\n  \"الخميس\": \"Thursday\",\r\n\r\n  \"الجمعة\": \"Friday\",\r\n\r\n  \"السبت\": \"Saturday\",\r\n\r\n  \"تعذر إتمام العملية\": \"Could not complete the operation\",\r\n\r\n  \"حدث خطأ\": \"An error occurred\",\r\n\r\n  \"تعذر الاتصال بخادم التطبيق\": \"Could not connect to the application server\",\r\n\r\n  \"خطأ في الاتصال\": \"Connection Error\",\r\n\r\n  \"البرنامج غير موجود\": \"Program not found\",\r\n\r\n  \"حالة غير صالحة\": \"Invalid status\",\r\n\r\n  \"نمط غير صالح\": \"Invalid schedule type\",\r\n\r\n  \"الفترة غير صالحة أو أطول من عام\": \"Invalid date range or a range longer than one year\",\r\n\r\n  \"وقت غير صالح\": \"Invalid time range\",\r\n\r\n  \"اختاري أيام اللقاءات\": \"Select the session weekdays\",\r\n\r\n  \"مواعيد اللقاءات يجب أن تقع داخل فترة الفعالية\": \"Session dates must fall within the event date range\",\r\n\r\n  \"لا توجد لقاءات في الفترة المحددة\": \"There are no sessions in the selected date range\",\r\n\r\n  \"غير موجود\": \"Not found\",\r\n\r\n  \"لا يمكن اعتماد ملف غير موجود\": \"A missing file cannot be approved\",\r\n\r\n  \"يجب إعادة فتح الفعالية أولًا\": \"Reopen the event first\",\r\n\r\n  \"لا يمكن إغلاق فعالية لم تنتهِ\": \"An event must be finished before it can be closed\",\r\n\r\n  \"المرفقات الأربعة لم تعتمد بعد\": \"All four documents must be approved first\",\r\n\r\n  \"البريد مكرر\": \"This email address is already in use\",\r\n\r\n  \"تغيير لغة الواجهة إلى الإنجليزية\": \"Switch interface to English\",\r\n\r\n  \"تغيير لغة الواجهة إلى العربية\": \"Switch interface to Arabic\",\r\n\r\n  \"تم تغيير لغة الواجهة إلى العربية\": \"Interface language changed to Arabic\",\r\n\r\n  \"تم تغيير لغة الواجهة إلى الإنجليزية\": \"Interface language changed to English\"\r\n\r\n};\r\n\r\nconst LANGUAGE_KEY = 'student-training-language';\r\n\r\nlet language = 'ar';\r\n\r\ntry { if(localStorage.getItem(LANGUAGE_KEY)==='en') language='en'; } catch (_) {}\r\n\r\nObject.assign(EN,{\"منصة إدارة التدريب الطلابي - مساحة الفريق\": \"Student Training Platform — Team Workspace\", \"مساحة مشتركة لتنظيم عمل الفريق\": \"A shared workspace for your team\", \"مساحة الفريق\": \"Team workspace\", \"تُحفظ السجلات في مساحة الفريق المشتركة، وتظهر التحديثات لجميع الأعضاء.\": \"Records are saved in your shared workspace. Updates are visible to every team member.\", \"أضيفي روابط الملفات وراجعي حالة اعتمادها هنا. لا توجد مزامنة تلقائية مع OneDrive.\": \"Add file links and review their approval status here. OneDrive does not sync automatically.\", \"تُحدّث حالة الملفات يدويًا من قِبل الفريق.\": \"File status is updated manually by your team.\"});\r\nconst translationPattern = new RegExp('(?<![\\u0600-\\u06ff])(?:' + Object.keys(EN).sort((a,b)=>b.length-a.length).map(key=>key.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&')).join('|') + ')(?![\\u0600-\\u06ff])','g');\r\n\r\nfunction tr(text){ return language==='en' ? (EN[text] ?? text) : text; }\r\n\r\nfunction translateUI(text){ return language==='en' ? text.replace(translationPattern,source=>EN[source]) : text; }\r\n\r\nfunction ui(parts,...values){return parts.reduce((result,part,index)=>result+translateUI(part)+(index<values.length?values[index]:''),'');}\r\n\r\nfunction currentLocale(){ return language==='en'?'en-GB':'ar-SA-u-ca-gregory'; }\r\n\r\nfunction eventCount(count){return language==='en'?`${count} ${count===1?'event':'events'}`:`${count} فعالية`;}\r\n\r\nfunction applyLanguage(){\r\n\r\n  document.documentElement.lang=language;\r\n\r\n  document.documentElement.dir=language==='en'?'ltr':'rtl';\r\n\r\n  document.querySelectorAll('[data-i18n]').forEach(node=>node.textContent=translateUI(node.dataset.i18n));\r\n\r\n  const button=document.getElementById('languageToggle');\r\n\r\n  const name=document.getElementById('languageName');\r\n\r\n  name.textContent=language==='ar'?'English':'العربية';\r\n\r\n  name.lang=language==='ar'?'en':'ar';\r\n\r\n  name.dir=language==='ar'?'ltr':'rtl';\r\n\r\n  button.setAttribute('aria-label',tr(language==='ar'?'تغيير لغة الواجهة إلى الإنجليزية':'تغيير لغة الواجهة إلى العربية'));\r\n\r\n  button.title=button.getAttribute('aria-label');\r\n\r\n}\r\n\r\nfunction setLanguage(next){\r\n\r\n  if(next!=='ar'&&next!=='en')return;\r\n\r\n  language=next;\r\n\r\n  try {localStorage.setItem(LANGUAGE_KEY,language);} catch (_) {}\r\n\r\n  applyLanguage();\r\n\r\n  if(typeof M!=='undefined'&&M.programs)render();\r\n\r\n  else if(typeof connectionError!=='undefined'&&connectionError)showConnectionError(connectionError);\r\n  if(typeof onLanguageChanged==='function')onLanguageChanged();\r\n\r\n  document.getElementById('languageStatus').textContent=tr(language==='en'?'تم تغيير لغة الواجهة إلى الإنجليزية':'تم تغيير لغة الواجهة إلى العربية');\r\n\r\n}\r\n\r\n"},"/static/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ar\" dir=\"rtl\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title data-i18n=\"منصة إدارة التدريب الطلابي - مساحة الفريق\">منصة إدارة التدريب الطلابي - مساحة الفريق</title><style>\r\n:root{font-family:Tahoma,'Segoe UI',sans-serif;color:#233042;background:#f4f6fa}*{box-sizing:border-box}body{margin:0}.layout{display:flex;min-height:100vh}aside{width:235px;flex-shrink:0;background:#173353;color:#fff;padding:24px 15px}aside h2{font-size:18px;margin:8px 5px 5px}aside p{color:#bbcfe3;font-size:11px;margin:0 5px 25px}nav button{background:transparent;color:#e7edf5;border:0;display:block;width:100%;padding:13px;text-align:right;margin-bottom:5px;border-radius:9px;cursor:pointer;font-size:14px}nav button.active,nav button:hover{background:#30567e}main{flex:1;min-width:0;padding:26px;max-width:1300px;margin:auto}h1{font-size:23px;margin:0 0 7px}h3{margin:0 0 16px;font-size:16px}.muted{color:#738195;font-size:12px}.top{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px;gap:15px}.tag{background:#e6effb;color:#2f609b;padding:6px 10px;border-radius:12px;font-size:12px}.warning{background:#fff0d9;color:#936321}.success{background:#e2f5e9;color:#257447}.card{background:white;border:1px solid #e0e7f0;border-radius:14px;padding:18px;margin-bottom:16px;box-shadow:0 2px 10px #192d4506}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{background:#fff;border:1px solid #e0e7f0;border-radius:12px;padding:18px}.stat strong{font-size:28px;display:block;margin-bottom:8px}.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:end;margin-bottom:15px}label{font-size:12px;font-weight:bold;display:block;margin:0 0 6px}input,select,textarea{font:inherit;border:1px solid #cfd9e7;border-radius:8px;padding:10px;width:100%;background:white;color:#263347;min-height:39px}textarea{min-height:75px}button{font:inherit;cursor:pointer}.btn{background:#235788;color:white;border:0;padding:10px 16px;border-radius:9px}.btn.secondary{background:#e7edf4;color:#254260}.btn.danger{background:#fee8e8;color:#9c2f38}.btn:disabled{opacity:.45;cursor:default}.field{flex:1;min-width:160px}.grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.hidden{display:none!important}.cal{display:grid;grid-template-columns:repeat(7,1fr);gap:4px}.cal-head{text-align:center;font-size:11px;color:#566779;padding:8px 0}.day{border:1px solid #e2e8f1;background:#fafbfd;min-height:92px;padding:5px;border-radius:7px;cursor:pointer;text-align:right;min-width:0}.day:hover{background:#eaf3fb}.day small{display:block;margin-bottom:6px}.event-pill{font-size:10px;line-height:1.6;padding:2px 4px;border-radius:5px;margin:3px 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse}td,th{text-align:right;padding:12px 8px;border-bottom:1px solid #e9eef4;font-size:13px}th{color:#6c7d91;font-weight:normal}.progress{height:8px;border-radius:10px;background:#e7edf3;overflow:hidden}.progress>div{background:#339b76;height:100%}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.tiny{font-size:12px;color:#68778a}.entry{padding:13px;border:1px solid #e0e7f0;border-radius:10px;margin-bottom:9px}.check{width:auto;min-height:0}.notice{padding:12px;background:#fff4e0;color:#825e23;border-radius:10px;font-size:12px;margin-bottom:16px}.days{display:flex;gap:10px;flex-wrap:wrap}.days label{font-size:12px;font-weight:normal}.days input{width:auto;min-height:0}dialog{border:0;border-radius:15px;padding:24px;width:min(730px,95vw);max-height:90vh;overflow:auto;box-shadow:0 20px 60px #15293e55}dialog::backdrop{background:#06182d87}.links a{color:#245d98}.list-inline{display:flex;gap:8px;flex-wrap:wrap}.ribbon{margin:5px 0 14px;border-right:3px solid #3985bd;padding-right:9px}.flex1{flex:1}.small-btn{border:0;border-radius:7px;padding:6px 10px;background:#edf2f8;color:#244666}.foot{font-size:11px;color:#7c8da0;margin-top:22px}@media(max-width:850px){.layout{display:block}aside{width:auto;padding:14px}nav{display:flex;overflow:auto;gap:6px}nav button{white-space:nowrap;width:auto}main{padding:14px}.stats{grid-template-columns:repeat(2,1fr)}.day{min-height:60px}.event-pill{font-size:9px}.grid2,.grid3{grid-template-columns:1fr}}@media(max-width:500px){.cal{gap:2px}.day{padding:2px}.day small{font-size:10px}.event-pill{font-size:8px}.stats{gap:6px}.stat{padding:11px}}\r\n\r\n/* Language controls share the existing navy palette and a 44px touch target. */\r\nnav button,td,th,.day{text-align:start}\r\n.ribbon{border-right:0;padding-right:0;border-inline-start:3px solid #3985bd;padding-inline-start:9px}\r\n.top{flex-wrap:wrap}.top>div:first-child{min-width:0}\r\n.top-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}\r\n.language-toggle{display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:44px;min-width:136px;padding:11px 18px;border:1px solid #173f69;border-radius:10px;background:#235788;color:#fff;font-size:15px;font-weight:700;box-shadow:0 3px 9px #17335320;transition:background .15s,transform .15s,box-shadow .15s;white-space:nowrap}\r\n.language-toggle svg{width:21px;height:21px;flex-shrink:0}\r\n.language-toggle:hover{background:#173f69;box-shadow:0 4px 12px #17335330}\r\n.language-toggle:active{transform:translateY(1px);background:#112f50}\r\n.language-toggle:focus-visible{outline:3px solid #3985bd;outline-offset:4px}\r\n.language-toggle:disabled{opacity:.5;cursor:default;transform:none}\r\n.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}\r\ninput[type=email],input[type=url],input[type=date],input[type=time]{direction:ltr}\r\n@media(max-width:600px){.top{align-items:flex-start;gap:16px}.top-actions{width:100%;justify-content:space-between;gap:10px}.language-toggle{min-width:136px}.top-actions>.tag{max-width:calc(100% - 146px)}h1{overflow-wrap:break-word}}\r\n@media(prefers-reduced-motion:reduce){.language-toggle{transition:none}}\r\n\r\n.session-info{display:grid;gap:5px;max-width:190px;min-width:0;font-size:13px}.session-info>b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.session-info>.tag{justify-self:start}.leader-badge{background:#e4eefb;color:#174f80;font-weight:700}.account-tags{display:flex;gap:6px;flex-wrap:wrap}.top-actions{justify-content:flex-end}#logoutButton{min-height:44px}.auth-forbidden{display:none!important}@media(max-width:600px){.top-actions{justify-content:space-between}.session-info{max-width:calc(100% - 110px)}.top-actions>#languageToggle{order:2}.top-actions>.tag{order:3}}\r\n\r\n.task-entry{padding:16px}.task-title{min-width:0;overflow-wrap:anywhere}.task-meta{margin-top:9px;line-height:1.7;overflow-wrap:anywhere}.task-notes{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.75;font-size:13px;background:#f5f8fc;border-radius:8px;padding:12px;color:#45566d}.task-preview{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.task-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:22px 0}.task-detail-grid dt{font-size:11px;color:#738195;margin-bottom:5px}.task-detail-grid dd{margin:0;font-size:13px;overflow-wrap:anywhere}.shared-refresh{min-height:40px}.shared-refresh:disabled{opacity:.5}.task-entry .controls{gap:8px}@media(max-width:500px){.task-entry{padding:12px}.task-detail-grid{grid-template-columns:1fr}.task-entry>.row{align-items:flex-start}}\r\n</style></head><body><div class=\"layout\"><aside><h2 data-i18n=\"منصة التدريب الطلابي\">منصة التدريب الطلابي</h2><p data-i18n=\"وحدة الدعم والتدريب الطلابي – 1448هـ\">وحدة الدعم والتدريب الطلابي – 1448هـ</p><nav id=\"nav\"><button class=\"active\" data-view=\"dashboard\" data-i18n=\"▦ لوحة القيادة\">▦ لوحة القيادة</button><button data-view=\"calendar\" data-i18n=\"▣ التقويم الفصلي\">▣ التقويم الفصلي</button><button data-view=\"events\" data-i18n=\"▤ الدورات والفعاليات\">▤ الدورات والفعاليات</button><button data-view=\"documents\" data-i18n=\"▧ متابعة المرفقات\">▧ متابعة المرفقات</button><button data-view=\"tasks\" data-i18n=\"☑ مهام الفريق\">☑ مهام الفريق</button><button data-view=\"users\" data-i18n=\"♙ المستخدمون\">♙ المستخدمون</button></nav></aside><main><div class=\"top\"><div><h1 id=\"heading\" data-i18n=\"لوحة القيادة\">لوحة القيادة</h1><span class=\"muted\" data-i18n=\"مساحة مشتركة لتنظيم عمل الفريق\">مساحة مشتركة لتنظيم عمل الفريق</span></div><div class=\"top-actions\"><div class=\"session-info\"><b id=\"sessionName\"></b><span id=\"sessionRole\" class=\"tag leader-badge\"></span></div><button type=\"button\" id=\"logoutButton\" class=\"btn secondary\" onclick=\"logout()\" data-auth-i18n=\"Log out\">Log out</button><button id=\"languageToggle\" class=\"language-toggle\" type=\"button\" aria-label=\"تغيير لغة الواجهة إلى الإنجليزية\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M3 12h18M12 3c3 3 4 6 4 9s-1 6-4 9c-3-3-4-6-4-9s1-6 4-9Z\"/></svg><span id=\"languageName\" lang=\"en\" dir=\"ltr\">English</span></button><span class=\"tag\" data-i18n=\"مساحة الفريق\">مساحة الفريق</span></div><span id=\"languageStatus\" class=\"sr-only\" role=\"status\" aria-live=\"polite\"></span></div><div class=\"notice\" data-auth-i18n=\"Your team shares this workspace. Your leader manages accounts, permissions, and password resets.\">يشترك فريقك في مساحة العمل. يدير القائد الحسابات والصلاحيات وإعادة تعيين كلمات المرور.</div><div id=\"content\"></div><div class=\"foot\" data-i18n=\"تُحفظ السجلات في مساحة الفريق المشتركة، وتظهر التحديثات لجميع الأعضاء.\">تُحفظ السجلات في مساحة الفريق المشتركة، وتظهر التحديثات لجميع الأعضاء.</div></main></div><dialog id=\"modal\"><div id=\"modalBody\"></div></dialog><script src=\"/static/i18n.js\"></script><script src=\"/static/auth-shared.js\"></script><script>\r\nlet M={},events=[],tasks=[],users=[],view='dashboard',month=new Date(2026,9,1),calendarMode='month',filterPath='all',selectedDay='2026-10-26';const $=s=>document.querySelector(s);const esc=x=>String(x??'').replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[ch]));const iso=d=>ui`${d.getFullYear()}-${('0'+(d.getMonth()+1)).slice(-2)}-${('0'+d.getDate()).slice(-2)}`;const local=s=>new Date(s+'T12:00:00');const plus=(s,n)=>{let d=local(s);d.setDate(d.getDate()+n);return iso(d)};const pname=id=>tr(M.programs.find(p=>p.id==id)?.name||'');const pathOf=id=>M.programs.find(p=>p.id==id)?.path_id;const pathName=id=>tr(M.paths.find(p=>p.id==id)?.name||'');const palettes=['#dbeafe','#def4e7','#eee4fa','#fff0d5'];const q=(val)=>encodeURIComponent(val);const option=(v,label,selected,translate=true)=>ui`<option value=\"${esc(v)}\" ${String(v)===String(selected)?'selected':''}>${esc(translate?tr(label):label)}</option>`;\r\nlet currentUser=null,csrfToken='',team=[],workspaceRevision=null;\r\nasync function api(url,method='GET',body){\r\n  const response=await fetch('/api'+url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(method!=='GET'?{'X-CSRF-Token':csrfToken}:{})},body:body?JSON.stringify(body):undefined});\r\n  if(!response.ok){if(response.status===401){location.replace('/login?expired=1');throw new Error(at('Please log in to continue.'))}const error=await response.json().catch(()=>({}));throw new Error(authMessage(typeof error.detail==='string'?error.detail:'Please check the entered values.'))}\r\n  return response.json();\r\n}\r\nasync function reload(){\r\n  const [identity,revision]=await Promise.all([api('/auth/me'),api('/workspace/revision')]);\r\n  currentUser=identity.user;csrfToken=identity.csrf_token;\r\n  const next=await Promise.all([api('/meta'),api('/events'),api('/tasks'),isLeader()?api('/users'):Promise.resolve([]),api('/team')]);\r\n  if(workspaceRevision!==null&&revision.revision<workspaceRevision)return;\r\n  [M,events,tasks,users,team]=next;workspaceRevision=revision.revision;\r\n  syncAuthShell();render();\r\n}\r\nfunction navigate(v){if(v==='users'&&!isLeader())v='dashboard';view=v;$('#nav').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render()}\r\n$('#nav').addEventListener('click',e=>{let b=e.target.closest('[data-view]');if(b)navigate(b.dataset.view)});\r\nfunction setContent(html,title){$('#heading').textContent=tr(title);$('#content').innerHTML=html;applyPermissions()}\r\nfunction card(label,n){return ui`<div class=\"stat\"><strong>${n}</strong><span class=\"tiny\">${esc(tr(label))}</span></div>`}\r\nfunction status(s){return ui`<span class=\"tag ${s==='مغلقة'||s==='مكتمل'?'success':s==='منتهية'?'warning':''}\">${esc(tr(s))}</span>`}\r\nfunction selectionPaths(sel='all',all=true){return ui`<select id=\"filterPath\" onchange=\"filterPath=this.value;render()\">${all?option('all','جميع المسارات',sel):''}${M.paths.map(p=>option(p.id,p.name,sel)).join('')}</select>`}\r\nfunction dashboard(){let ended=events.filter(e=>['منتهية','مغلقة'].includes(e.status));let overdue=tasks.filter(t=>t.status!=='مكتمل'&&t.due<iso(new Date()));setContent(ui`<div class=\"stats\">${card('المسارات المعتمدة',4)}${card('البرامج المعتمدة',16)}${card('الفعاليات المسجلة',events.length)}${card('المهام المتأخرة',overdue.length)}</div><div class=\"grid2\" style=\"margin-top:16px\"><section class=\"card\"><h3>الفعاليات حسب المسار</h3>${M.paths.map(p=>ui`<div class=\"row entry\"><span>${esc(tr(p.name))}</span><b>${eventCount(events.filter(e=>pathOf(e.program_id)===p.id).length)}</b></div>`).join('')}</section><section class=\"card\"><h3>متابعة التنفيذ</h3><div class=\"entry\">فعاليات منتهية أو مغلقة: <b>${ended.length}</b></div><div class=\"entry\">فعاليات مجدولة: <b>${events.filter(e=>e.status==='مجدولة').length}</b></div><div class=\"entry\">مهام تحت العمل: <b>${tasks.filter(t=>t.status==='تحت العمل').length}</b></div><div class=\"row\"><button class=\"btn\" onclick=\"navigate('calendar')\">عرض التقويم</button><button class=\"btn secondary\" onclick=\"navigate('documents')\">متابعة الملفات</button></div></section></div>`,'لوحة القيادة')}\r\nfunction calendar(){let first=new Date(month.getFullYear(),month.getMonth(),1,12),start=new Date(first);start.setDate(1-first.getDay());let dates=calendarMode==='month'?Array.from({length:42},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);return iso(d)}):Array.from({length:7},(_,i)=>plus(selectedDay,-local(selectedDay).getDay()+i));let records=events.filter(e=>filterPath==='all'||pathOf(e.program_id)==filterPath);let heads=['أحد','اثنين','ثلاثاء','أربعاء','خميس','جمعة','سبت'].map(x=>ui`<div class=\"cal-head\">${tr(x)}</div>`).join('');let cells=dates.map(d=>{let es=records.filter(e=>e.sessions.includes(d));return ui`<button class=\"day\" onclick=\"selectedDay='${d}';render()\" style=\"${d===selectedDay?'border:2px solid #3b83c3;':''}\"><small>${Number(d.slice(8))}</small>${es.slice(0,3).map(e=>ui`<div class=\"event-pill\" style=\"background:${palettes[(pathOf(e.program_id)-1)%4]}\">${esc(e.name)}</div>`).join('')}${es.length>3?translateUI('<small>+ المزيد</small>'):''}</button>`}).join('');let dayEvents=records.filter(e=>e.sessions.includes(selectedDay));setContent(ui`<div class=\"controls\"><div class=\"field\"><label>المسار</label>${selectionPaths(filterPath)}</div><div class=\"field\"><label>عرض التقويم</label><select onchange=\"calendarMode=this.value;render()\">${option('month','شهري',calendarMode)}${option('week','أسبوعي',calendarMode)}</select></div><button class=\"btn\" onclick=\"eventForm()\">+ فعالية جديدة</button></div><section class=\"card\"><div class=\"row\" style=\"margin-bottom:15px\"><div><button class=\"small-btn\" onclick=\"moveMonth(-1)\">السابق</button> <button class=\"small-btn\" onclick=\"moveMonth(1)\">التالي</button></div><b>${new Intl.DateTimeFormat(currentLocale(),{month:'long',year:'numeric'}).format(month)}</b></div><div class=\"cal\">${heads}${cells}</div></section><section class=\"card\"><h3>لقاءات ${selectedDay}</h3>${dayEvents.length?dayEvents.map(e=>ui`<div class=\"entry row\"><div><b>${esc(e.name)}</b><div class=\"tiny\">${esc(pname(e.program_id))} | ${e.time_start} – ${e.time_end}</div></div><button class=\"small-btn\" onclick=\"eventDetails('${e.id}')\">فتح</button></div>`).join(''):translateUI('<span class=\"muted\">لا توجد لقاءات في هذا اليوم.</span>')}</section>`,'التقويم الفصلي')}\r\nfunction moveMonth(n){if(calendarMode==='month'){month.setMonth(month.getMonth()+n)}else selectedDay=plus(selectedDay,n*7);render()}\r\nfunction eventsView(){let r=events.filter(e=>filterPath==='all'||pathOf(e.program_id)==filterPath);setContent(ui`<div class=\"controls\"><div class=\"field\"><label>تصفية المسار</label>${selectionPaths(filterPath)}</div><button class=\"btn\" onclick=\"eventForm()\">+ إضافة فعالية</button></div><section class=\"card tablewrap\"><table><thead><tr><th>الفعالية</th><th>البرنامج</th><th>الفترة</th><th>اللقاءات</th><th>الحالة</th><th></th></tr></thead><tbody>${r.map(e=>ui`<tr><td><b>${esc(e.name)}</b><div class=\"tiny\">${esc(e.owner)}</div></td><td>${esc(pname(e.program_id))}</td><td>${e.start} إلى ${e.end}</td><td>${e.sessions.length}</td><td>${status(e.status)}</td><td><button class=\"small-btn\" onclick=\"eventDetails('${e.id}')\">التفاصيل</button></td></tr>`).join('')}</tbody></table>${!r.length?translateUI('<p class=\"muted\">لم تُسجل فعاليات بعد.</p>'):''}</section>`,'الدورات والفعاليات')}\r\nfunction modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal();applyPermissions()}function closeModal(){$('#modal').close()}\r\nfunction eventForm(id){let e=events.find(x=>x.id===id)||{name:'',program_id:101,start:selectedDay,end:selectedDay,schedule:'single',days:[0,2],custom_dates:[],time_start:'16:00',time_end:'18:00',owner:'',status:'مجدولة'};modal(ui`<h3>${tr(id?'تعديل الفعالية':'إضافة فعالية')}</h3><form id=\"eventForm\" onsubmit=\"submitEvent(event,'${id||''}')\"><div class=\"grid2\"><div><label>اسم الفعالية</label><input name=\"name\" required value=\"${esc(e.name)}\"></div><div><label>البرنامج المعتمد</label><select name=\"program_id\">${M.paths.map(p=>ui`<optgroup label=\"${esc(tr(p.name))}\">${M.programs.filter(x=>x.path_id===p.id).map(pr=>option(pr.id,pr.name,e.program_id)).join('')}</optgroup>`).join('')}</select></div><div><label>تاريخ البداية</label><input name=\"start\" type=\"date\" required value=\"${e.start}\"></div><div><label>تاريخ النهاية</label><input name=\"end\" type=\"date\" required value=\"${e.end}\"></div><div><label>نمط الجدولة</label><select name=\"schedule\" onchange=\"scheduleFields()\">${[['single','يوم واحد'],['consecutive','أيام متتالية'],['weekly','لقاءات أسبوعية'],['custom','مواعيد مخصصة']].map(p=>option(p[0],p[1],e.schedule)).join('')}</select></div><div><label>الحالة</label><select name=\"status\">${M.statuses.filter(s=>s!=='مغلقة'||e.status==='مغلقة').map(s=>option(s,s,e.status)).join('')}</select></div><div><label>وقت البداية</label><input name=\"time_start\" type=\"time\" required value=\"${e.time_start}\"></div><div><label>وقت النهاية</label><input name=\"time_end\" type=\"time\" required value=\"${e.time_end}\"></div><div><label>المنسق</label><input name=\"owner\" value=\"${esc(e.owner)}\"></div></div><div id=\"weeklyBox\"><label>أيام اللقاءات الأسبوعية</label><div class=\"days\">${['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'].map((d,i)=>ui`<label><input class=\"check\" type=\"checkbox\" name=\"days\" value=\"${i}\" ${e.days.includes(i)?'checked':''}> ${tr(d)}</label>`).join('')}</div></div><div id=\"customBox\"><label>تواريخ اللقاءات المخصصة (تاريخ في كل سطر)</label><textarea name=\"custom_dates\" placeholder=\"2026-11-01&#10;2026-11-05\">${(e.custom_dates||[]).join('\\n')}</textarea></div><div class=\"controls\" style=\"margin-top:17px\"><button class=\"btn\" type=\"submit\">حفظ الفعالية</button><button type=\"button\" class=\"btn secondary\" onclick=\"closeModal()\">إلغاء</button></div></form>`);scheduleFields()}\r\nfunction scheduleFields(){let s=$('#eventForm').elements.schedule.value;$('#weeklyBox').classList.toggle('hidden',s!=='weekly');$('#customBox').classList.toggle('hidden',s!=='custom')}\r\nasync function submitEvent(evt,id){evt.preventDefault();let f=evt.target;let v={name:f.elements.name.value,program_id:Number(f.elements.program_id.value),start:f.elements.start.value,end:f.elements.end.value,schedule:f.elements.schedule.value,days:[...f.querySelectorAll('input[name=days]:checked')].map(x=>Number(x.value)),custom_dates:f.elements.custom_dates.value.split(/\\s+/).filter(Boolean),time_start:f.elements.time_start.value,time_end:f.elements.time_end.value,owner:f.elements.owner.value,status:f.elements.status.value};try{await api('/events'+(id?'/'+id:''),id?'PUT':'POST',v);closeModal();await reload()}catch(e){alert(e.message)}}\r\nfunction eventDetails(id){let e=events.find(x=>x.id===id);modal(ui`<h3>${esc(e.name)}</h3><div class=\"entry\">${esc(pathName(pathOf(e.program_id)))} ${language==='en'?'→':'←'} ${esc(pname(e.program_id))}</div><p>الفترة: ${e.start} – ${e.end} | ${esc(tr(e.status))}</p><p>المنسق: ${esc(e.owner||tr('غير محدد'))}</p><h3>اللقاءات (${e.sessions.length})</h3><div style=\"max-height:180px;overflow:auto\">${e.sessions.map(d=>ui`<div class=\"entry\">${d} | ${e.time_start} – ${e.time_end}</div>`).join('')}</div><div class=\"controls\"><button class=\"btn\" onclick=\"closeModal();eventForm('${e.id}')\">تعديل</button><button class=\"btn secondary\" onclick=\"closeModal();navigate('documents')\">المرفقات</button><button class=\"btn danger\" onclick=\"removeEvent('${e.id}')\">حذف</button><button class=\"btn secondary\" onclick=\"closeModal()\">إغلاق</button></div>`)}\r\nasync function removeEvent(id){if(!confirm(tr('هل تريد حذف الفعالية نهائيًا؟')))return;try{await api('/events/'+id,'DELETE');closeModal();await reload()}catch(e){alert(e.message)}}\r\nasync function documents(){let ended=events.filter(e=>['منتهية','مغلقة'].includes(e.status));let results=await Promise.all(ended.map(e=>api('/documents/'+e.id)));setContent(ui`<section class=\"card\"><h3>توثيق الفعاليات المنتهية</h3><p class=\"tiny\">أضيفي روابط الملفات وراجعي حالة اعتمادها هنا. لا توجد مزامنة تلقائية مع OneDrive.</p>${ended.map((e,i)=>{let docs=results[i],present=docs.filter(d=>d.present).length,approved=docs.filter(d=>d.approved).length;return ui`<div class=\"entry\"><div class=\"row\"><b>${esc(e.name)}</b>${status(e.status)}</div><p class=\"tiny\">المرفقات الموجودة: ${present}/4 | المعتمدة: ${approved}/4</p><div class=\"progress\"><div style=\"width:${approved*25}%\"></div></div><div style=\"margin-top:10px\"><button class=\"small-btn\" onclick=\"docDetails('${e.id}')\">مراجعة المرفقات</button></div></div>`}).join('')}${!ended.length?translateUI('<p class=\"muted\">لم تُحدد فعاليات منتهية بعد. حدّثي حالة إحدى الفعاليات إلى «منتهية» لتجربة التوثيق.</p>'):''}</section>`,'متابعة المرفقات')}\r\nasync function docDetails(id){let e=events.find(x=>x.id===id),docs=await api('/documents/'+id);modal(ui`<h3>مرفقات: ${esc(e.name)}</h3><p class=\"muted\">تُحدّث حالة الملفات يدويًا من قِبل الفريق.</p>${docs.map((d,i)=>ui`<div class=\"entry\"><div class=\"row\"><b>${esc(tr(d.kind))}</b>${d.approved?status('مكتمل'):d.present?status('بانتظار الاعتماد'):status('ناقص')}</div><div class=\"controls\"><label><input class=\"check\" type=\"checkbox\" id=\"p${i}\" ${d.present?'checked':''} ${e.status==='مغلقة'?'disabled':''}> موجود</label><label><input class=\"check\" type=\"checkbox\" id=\"a${i}\" ${d.approved?'checked':''} ${e.status==='مغلقة'?'disabled':''}> معتمد</label></div><input id=\"u${i}\" placeholder=\"رابط الملف (اختياري)\" value=\"${esc(d.url)}\" ${e.status==='مغلقة'?'disabled':''}><button class=\"small-btn\" ${e.status==='مغلقة'?'disabled':''} onclick=\"saveDoc('${id}',${i},'${q(d.kind)}')\">حفظ حالة الملف</button></div>`).join('')}<div class=\"controls\"><button class=\"btn\" onclick=\"closeActivity('${id}')\" ${e.status==='مغلقة'?'disabled':''}>اعتماد إغلاق الفعالية</button><button class=\"btn secondary\" onclick=\"closeModal()\">إغلاق</button></div>`)}\r\nasync function saveDoc(id,i,kind){try{await api('/documents/'+id+'/'+q(decodeURIComponent(kind)),'PUT',{present:$('#p'+i).checked,approved:$('#a'+i).checked,url:$('#u'+i).value});await docDetails(id)}catch(e){alert(e.message)}}\r\nasync function closeActivity(id){try{await api('/events/'+id+'/close','POST');closeModal();await reload()}catch(e){alert(e.message)}}\r\nfunction tasksView(){\r\n  const overdue=tasks.filter(task=>task.status!=='مكتمل'&&task.due<iso(new Date())).length;\r\n  setContent(ui`<div class=\"stats\">${card('إجمالي المهام',tasks.length)}${card('تحت العمل',tasks.filter(task=>task.status==='تحت العمل').length)}${card('مكتملة',tasks.filter(task=>task.status==='مكتمل').length)}${card('متأخرة',overdue)}</div><section class=\"card\" style=\"margin-top:15px\"><div class=\"row\"><div><h3>مهام الفريق</h3><p class=\"tiny\">${at('Tasks and linked events are visible to everyone in this workspace.')}</p></div><div class=\"controls\"><button class=\"btn secondary shared-refresh\" type=\"button\" onclick=\"refreshSharedWork()\">${at('Refresh')}</button><button class=\"btn\" onclick=\"taskForm()\">+ ${at('New task')}</button></div></div><p id=\"workspaceSyncStatus\" class=\"tiny\" role=\"status\">${at('Updates automatically while this page is open.')}</p>${tasks.map(task=>{\r\n    const linked=events.find(event=>event.id===task.event_id);\r\n    const owner=task.assignee_name||task.owner||at('Unassigned');\r\n    return ui`<article class=\"entry task-entry\" data-task-id=\"${esc(task.id)}\"><div class=\"row\"><b class=\"task-title\">${esc(task.title)}</b><div class=\"account-tags\">${task.assignee_id===currentUser.id?ui`<span class=\"tag success\">${at('Assigned to you')}</span>`:''}${status(task.status)}</div></div><div class=\"tiny task-meta\">${at('Assigned to')}: <b>${esc(owner)}</b> · ${at('Due')}: <bdi>${esc(task.due)}</bdi> · ${at('Priority')}: ${esc(tr(task.priority))}</div><div class=\"tiny task-meta\">${at('Related event')}: ${linked?esc(linked.name):at('General task')}</div>${task.notes?ui`<p class=\"task-notes task-preview\">${esc(task.notes)}</p>`:''}<div class=\"controls\" style=\"margin:12px 0 0\"><select aria-label=\"${at('Task status')}: ${esc(task.title)}\" style=\"max-width:170px\" onchange=\"setTaskStatus('${task.id}',this.value)\">${['غير مكتمل','تحت العمل','مكتمل'].map(status=>option(status,status,task.status)).join('')}</select><button class=\"small-btn\" type=\"button\" onclick=\"taskDetails('${task.id}')\">${at('View details')}</button><button class=\"small-btn\" onclick=\"taskForm('${task.id}')\">تعديل</button><button class=\"small-btn\" onclick=\"deleteTask('${task.id}')\">حذف</button></div></article>`;\r\n  }).join('')}${!tasks.length?ui`<p class=\"muted\">${at('No shared tasks yet.')}</p>`:''}</section>`,'إدارة مهام الفريق');\r\n}\r\nfunction taskDetails(id){\r\n  const task=tasks.find(item=>item.id===id);if(!task)return;\r\n  const linked=events.find(event=>event.id===task.event_id);\r\n  modal(ui`<h3>${esc(task.title)}</h3><div class=\"row\">${status(task.status)}${task.assignee_id===currentUser.id?ui`<span class=\"tag success\">${at('Assigned to you')}</span>`:''}</div><dl class=\"task-detail-grid\"><div><dt>${at('Assigned to')}</dt><dd>${esc(task.assignee_name||task.owner||at('Unassigned'))}</dd></div><div><dt>${at('Due')}</dt><dd><bdi>${esc(task.due)}</bdi></dd></div><div><dt>${at('Priority')}</dt><dd>${esc(tr(task.priority))}</dd></div><div><dt>${at('Related event')}</dt><dd>${linked?esc(linked.name):at('General task')}</dd></div></dl><h3>${at('Instructions & notes')}</h3><p class=\"task-notes\">${esc(task.notes||at('No additional instructions.'))}</p><div class=\"controls\">${linked?ui`<button type=\"button\" class=\"btn secondary\" onclick=\"closeModal();eventDetails('${linked.id}')\">${at('Open linked event')}</button>`:''}<button type=\"button\" class=\"btn secondary\" onclick=\"closeModal()\">${at('Close')}</button></div>`);\r\n}\r\nfunction taskForm(id){\r\n  const task=tasks.find(item=>item.id===id)||{title:'',owner:'',due:iso(new Date()),priority:'متوسطة',status:'غير مكتمل',event_id:'',notes:'',assignee_id:null};\r\n  const selected=task.assignee_id||(task.owner?'__legacy__':'');\r\n  const keep=task.assignee_id&&!team.some(person=>person.id===task.assignee_id)?option(task.assignee_id,task.assignee_name||task.owner,selected,false):'';\r\n  modal(ui`<h3>${tr(id?'تعديل المهمة':'إضافة مهمة')}</h3><form id=\"taskForm\" onsubmit=\"submitTask(event,'${id||''}')\"><div class=\"grid2\"><div><label for=\"taskTitle\">العنوان</label><input id=\"taskTitle\" name=\"title\" required maxlength=\"200\" value=\"${esc(task.title)}\"></div><div><label for=\"taskAssignee\">${at('Assigned to')}</label><select id=\"taskAssignee\" name=\"assignee_id\">${option('',at('Unassigned'),selected,false)}${task.owner&&!task.assignee_id?option('__legacy__',task.owner,selected,false):''}${keep}${team.map(person=>option(person.id,person.name+' · '+roleLabel(person.role),selected,false)).join('')}</select><p class=\"tiny\">${at('Everyone can see this task, including members who are not assigned to it.')}</p></div><div><label for=\"taskDue\">تاريخ الاستحقاق</label><input id=\"taskDue\" type=\"date\" name=\"due\" required value=\"${task.due}\"></div><div><label for=\"taskPriority\">الأولوية</label><select id=\"taskPriority\" name=\"priority\">${['منخفضة','متوسطة','عالية'].map(value=>option(value,value,task.priority)).join('')}</select></div><div><label for=\"taskStatus\">الحالة</label><select id=\"taskStatus\" name=\"status\">${['غير مكتمل','تحت العمل','مكتمل'].map(value=>option(value,value,task.status)).join('')}</select></div><div><label for=\"taskEvent\">الفعالية المرتبطة</label><select id=\"taskEvent\" name=\"event_id\">${option('',at('General task'),task.event_id,false)}${events.map(event=>option(event.id,event.name,task.event_id,false)).join('')}</select></div></div><label for=\"taskNotes\">${at('Instructions & notes')}</label><textarea id=\"taskNotes\" name=\"notes\">${esc(task.notes)}</textarea><div class=\"controls\"><button class=\"btn\">حفظ</button><button type=\"button\" class=\"btn secondary\" onclick=\"closeModal()\">إلغاء</button></div></form>`);\r\n}\r\nfunction taskValue(form){\r\n  const id=form.assignee_id.value;\r\n  const person=team.find(item=>item.id===id);\r\n  const owner=id==='__legacy__'?form.assignee_id.selectedOptions[0].textContent:(person?.name||'');\r\n  return {title:form.title.value,owner,due:form.due.value,priority:form.priority.value,status:form.status.value,event_id:form.event_id.value||null,notes:form.notes.value,assignee_id:id&&id!=='__legacy__'?id:null};\r\n}\r\nasync function submitTask(e,id){e.preventDefault();try{await api('/tasks'+(id?'/'+id:''),id?'PUT':'POST',taskValue(e.target.elements));closeModal();await reload()}catch(x){alert(x.message)}}\r\nasync function setTaskStatus(id,s){let t=tasks.find(x=>x.id===id);try{await api('/tasks/'+id+'/status','PATCH',{status:s});await reload()}catch(e){alert(e.message)}}\r\nasync function deleteTask(id){if(confirm(tr('حذف المهمة؟'))){await api('/tasks/'+id,'DELETE');await reload()}}\r\nfunction usersView(){\r\n  setContent(ui`<section class=\"card\"><div class=\"row\"><div><h3>${at('Accounts & permissions')}</h3><p class=\"muted\">${at('The leader controls access and assigns each account a role.')}</p></div><button class=\"btn\" onclick=\"userForm()\">+ ${at('Add account')}</button></div>${users.map(user=>ui`<div class=\"entry\"><div class=\"row\"><div><b>${esc(user.name)}</b><div class=\"tiny\">${esc(user.email)} | ${esc(roleLabel(user.role))}</div></div><div class=\"account-tags\"><span class=\"tag ${user.role==='admin'?'leader-badge':''}\">${esc(roleLabel(user.role))}</span>${status(user.active?'نشط':'معطل')}${!user.has_login?ui`<span class=\"tag warning\">${at('No login yet')}</span>`:''}</div></div><button class=\"small-btn\" onclick=\"userForm('${user.id}')\">${at('Edit account')}</button></div>`).join('')}</section><section class=\"card\"><h3>${at('Role permissions')}</h3><div class=\"entry\"><b>${at('Leader / Admin')}</b><p class=\"tiny\">${at('Full access, account management, document approvals, and event closure.')}</p></div><div class=\"entry\"><b>${at('Program Coordinator')}</b><p class=\"tiny\">${at('Manage events, team tasks, and unapproved documents.')}</p></div><div class=\"entry\"><b>${at('Team Member')}</b><p class=\"tiny\">${at('View the workspace and update team task status.')}</p></div><div class=\"entry\"><b>${at('Viewer')}</b><p class=\"tiny\">${at('Read-only access to the workspace.')}</p></div></section>`,at('Accounts & permissions'));\r\n}\r\nfunction userForm(id){\r\n  const user=users.find(item=>item.id===id)||{name:'',email:'',role:'member',active:1,has_login:false};\r\n  modal(ui`<h3>${at(id?'Edit account':'Add account')}</h3><form onsubmit=\"submitUser(event,'${id||''}')\"><div class=\"grid2\"><div><label for=\"accountName\">${at('Full name')}</label><input id=\"accountName\" name=\"name\" required maxlength=\"100\" value=\"${esc(user.name)}\" autocomplete=\"name\"></div><div><label for=\"accountEmail\">${at('Email address')}</label><input id=\"accountEmail\" name=\"email\" type=\"email\" required maxlength=\"254\" value=\"${esc(user.email)}\" autocomplete=\"email\"></div><div><label for=\"accountRole\">${at('Role')}</label><select id=\"accountRole\" name=\"role\">${['admin','coordinator','member','viewer'].map(role=>option(role,roleLabel(role),user.role,false)).join('')}</select></div><div><label for=\"accountPassword\">${at(id?'New password (optional)':'Password')}</label><input id=\"accountPassword\" name=\"password\" type=\"password\" minlength=\"15\" maxlength=\"128\" ${id?'':'required'} autocomplete=\"new-password\"><p class=\"tiny\">${at(id?'Leave blank to keep the current password. Setting a password enables login and signs out existing sessions.':'Use at least 15 characters. Share the password privately with the account owner.')}</p></div></div><label style=\"margin:14px 0\"><input class=\"check\" name=\"active\" type=\"checkbox\" ${user.active?'checked':''}> ${at('Active account')}</label><div class=\"controls\"><button class=\"btn\">${at('Save account')}</button><button type=\"button\" class=\"btn secondary\" onclick=\"closeModal()\">${at('Cancel')}</button></div></form>`);\r\n}\r\nasync function submitUser(event,id){\r\n  event.preventDefault();const form=event.target.elements;const button=event.submitter;button.disabled=true;\r\n  try{await api('/users'+(id?'/'+id:''),id?'PUT':'POST',{name:form.name.value,email:form.email.value,role:form.role.value,active:form.active.checked,password:form.password.value});closeModal();await reload()}catch(error){alert(error.message)}finally{button.disabled=false}\r\n}\r\nfunction render(){if(view==='users'&&!isLeader())view='dashboard';if(view==='dashboard')dashboard();if(view==='calendar')calendar();if(view==='events')eventsView();if(view==='documents')documents().catch(e=>alert(e.message));if(view==='tasks')tasksView();if(view==='users')usersView();applyPermissions()}\r\nlet connectionError=null;\r\nfunction showConnectionError(error){connectionError=error;setContent(ui`<div class=\"notice\">تعذر الاتصال بخادم التطبيق: ${esc(tr(error.message))}</div>`,'خطأ في الاتصال')}\r\napplyLanguage();\r\n$('#languageToggle').addEventListener('click',()=>setLanguage(language==='ar'?'en':'ar'));\r\nwindow.addEventListener('DOMContentLoaded',()=>{applyLanguage();reload().catch(showConnectionError)});\r\n</script><script src=\"/static/workspace-auth.js\"></script><script src=\"/static/workspace-sync.js\"></script></body></html>\r\n"},"/static/workspace-auth.js":{"type":"text/javascript; charset=utf-8","body":"function isLeader(){return currentUser?.role==='admin';}\r\nfunction canManage(){return ['admin','coordinator'].includes(currentUser?.role);}\r\nfunction canUpdateTasks(){return ['admin','coordinator','member'].includes(currentUser?.role);}\r\nfunction syncAuthShell(){\r\n  translateAccountText();\r\n  document.getElementById('sessionName').textContent=currentUser?.name||'';\r\n  document.getElementById('sessionRole').textContent=currentUser?roleLabel(currentUser.role):'';\r\n  document.querySelector('[data-view=\"users\"]').hidden=!isLeader();\r\n  document.querySelector('[data-view=\"users\"]').classList.toggle('auth-forbidden',!isLeader());\r\n}\r\nfunction applyPermissions(){\r\n  document.querySelectorAll('#content button[onclick],#modalBody button[onclick]').forEach(button=>{\r\n    const action=button.getAttribute('onclick');\r\n    if(/eventForm\\(|removeEvent\\(|taskForm\\(|deleteTask\\(/.test(action)&&!canManage())button.hidden=true;\r\n    if(/userForm\\(|closeActivity\\(/.test(action)&&!isLeader())button.hidden=true;\r\n    if(button.hidden)button.classList.add('auth-forbidden');\r\n    const documentMatch=action.match(/saveDoc\\('[^']+',\\s*(\\d+)/);\r\n    if(documentMatch){\r\n      const index=documentMatch[1];\r\n      const approved=document.getElementById('a'+index)?.checked;\r\n      if(!canManage()||(!isLeader()&&approved))button.disabled=true;\r\n    }\r\n  });\r\n  document.querySelectorAll('#content select[onchange*=\"setTaskStatus\"]').forEach(select=>select.disabled=!canUpdateTasks());\r\n  document.querySelectorAll('#modalBody input[id^=\"a\"]').forEach(input=>{if(!isLeader())input.disabled=true;});\r\n  document.querySelectorAll('#modalBody input[id^=\"p\"],#modalBody input[id^=\"u\"]').forEach(input=>{\r\n    const index=input.id.slice(1);\r\n    if(!/^\\d+$/.test(index))return;\r\n    if(!canManage()||(!isLeader()&&document.getElementById('a'+index)?.checked))input.disabled=true;\r\n  });\r\n}\r\nfunction onLanguageChanged(){syncAuthShell();applyPermissions();}\r\nasync function logout(){\r\n  const button=document.getElementById('logoutButton');button.disabled=true;\r\n  try{await api('/auth/logout','POST');location.replace('/login');}\r\n  catch(error){alert(error.message);button.disabled=false;}\r\n}\r\n"},"/static/workspace-sync.js":{"type":"text/javascript; charset=utf-8","body":"// One lightweight revision check every 15s; never replace a form while it is edited.\r\nlet sharedPollTimer=null,sharedPollBusy=false;\r\nfunction canRefreshSharedWork(){\r\n  return currentUser&&workspaceRevision!==null&&!document.hidden&&!document.querySelector('dialog[open]')&&!document.activeElement?.matches('input,textarea,select');\r\n}\r\nasync function pollSharedWork(){\r\n  if(sharedPollBusy||!canRefreshSharedWork())return;\r\n  sharedPollBusy=true;\r\n  try{\r\n    const latest=await api('/workspace/revision');\r\n    if(latest.revision!==workspaceRevision&&canRefreshSharedWork())await reload();\r\n  }catch(_){const status=document.getElementById('workspaceSyncStatus');if(status)status.textContent=at('Updates paused. Use Refresh to retry.');}\r\n  finally{sharedPollBusy=false;}\r\n}\r\nasync function refreshSharedWork(){\r\n  if(sharedPollBusy)return;\r\n  sharedPollBusy=true;\r\n  document.querySelectorAll('.shared-refresh').forEach(button=>button.disabled=true);\r\n  try{await reload();}catch(error){alert(error.message);}\r\n  finally{sharedPollBusy=false;document.querySelectorAll('.shared-refresh').forEach(button=>button.disabled=false);}\r\n}\r\nfunction startSharedSync(){if(sharedPollTimer===null)sharedPollTimer=setInterval(pollSharedWork,15000);}\r\nwindow.addEventListener('DOMContentLoaded',()=>{\r\n  startSharedSync();\r\n  document.getElementById('modal').addEventListener('close',pollSharedWork);\r\n});\r\ndocument.addEventListener('visibilitychange',()=>{if(!document.hidden)pollSharedWork();});\r\nwindow.addEventListener('focus',pollSharedWork);\r\nwindow.addEventListener('pageshow',startSharedSync);\r\nwindow.addEventListener('pagehide',()=>{clearInterval(sharedPollTimer);sharedPollTimer=null;});\r\n"}};
